const __pageData = JSON.parse('{"title":"SpringBoot配置文件","description":"本章最后一篇，讲 SpringBoot 的三种配置文件格式（properties、yaml、yml）、yml 的四条语法规则与对象/数组写法，以及以 0 开头的值必须加引号的八进制坑（本机实测 0123456 读出来变成 42798），最后把整套数据源配置从 properties 改写成 yml","frontmatter":{"title":"SpringBoot配置文件","published":"2026-09-29T00:00:00.000Z","description":"本章最后一篇，讲 SpringBoot 的三种配置文件格式（properties、yaml、yml）、yml 的四条语法规则与对象/数组写法，以及以 0 开头的值必须加引号的八进制坑（本机实测 0123456 读出来变成 42798），最后把整套数据源配置从 properties 改写成 yml","tags":["JavaWeb","SpringBoot","MyBatis"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-56-springboot-config-file.webp","order":56,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/56-SpringBoot配置文件.md","filePath":"posts/学习文档/JavaWeb学习笔记/56-SpringBoot配置文件.md"}');
